    "    W.add(\"D\", \"data\", D);",
    "    W.add(\"CLK\", \"clk\", CLK);",
    "    W.add(\"Q\", \"out\", Q);",
    "",
    "    for (int t = 0; t < N; t++) {",
    "    }",
    "}",
